Q="%E5%85%AC%E8%AF%81%E5%91%98%E6%83%A9%E6%88%92%E8%A7%84%E5%88%99"; echo "== google"; curl -sL -m 12 "https://www.google.com/search?q=$Q+%E8%AF%95%E8%A1%8C+%E5%85%A8%E6%96%87&num=20&hl=zh-CN" -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36" -o /tmp/g.html -w "%{http_code} %{size_download}
"; grep -oP 'href="/url\?q=\K[^&]+' /tmp/g.html | head -20; echo "== toutiao"; curl -sL -m 12 "https://so.toutiao.com/search?keyword=$Q&pd=synthesis" -A "Mozilla/5.0" -o /tmp/tt.html -w "%{http_code} %{size_download}
"; grep -oP '"url":"[^"]+"' /tmp/tt.html | head -10; echo "== yandex"; curl -sL -m 12 "https://yandex.com/search/?text=$Q" -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/120" -o /tmp/y.html -w "%{http_code} %{size_download}
"
